import com.comsol.model.*;import com.comsol.model.util.*;import java.io.*;import java.util.*;
public class NTypeResumeSweep{public static void main(String[]a)throws Exception{String r="D:/Github_codes/Flexible_Conductive_Film_CourseDesign_UESTC_24",p=r+"/COMSOL_Models/Pressure_Sensor_NType_SingleCrystal.mph",q=r+"/COMSOL_Models/Pressure_Sensor_NType_SingleCrystal_Sweep.mph",d=r+"/Simulation_Results/Material_Replacement";new File(d).mkdirs();TreeMap<Integer,String>x=new TreeMap<Integer,String>();File c=new File(d,"nSi_pressure_sweep.csv");if(c.exists()){BufferedReader b=new BufferedReader(new FileReader(c));b.readLine();String s;while((s=b.readLine())!=null)x.put(Integer.parseInt(s.split(",")[0]),s);b.close();}PrintWriter l=new PrintWriter(new FileWriter(new File(d,"nSi_pressure_sweep_solver_log.txt"),true));ModelUtil.connect("localhost",2036);try{Model m=ModelUtil.load("nscan",p);m.save(q);boolean z=m.study("std1").feature("param").isActive();m.study("std1").feature("param").active(false);for(String u:a){int k=Integer.parseInt(u);if(x.containsKey(k)){l.println("SKIP,"+k);continue;}m.param().set("p1",k+"[kPa]");l.println("START,"+k);m.study("std1").run();String t="ev"+k;m.result().numerical().create(t,"EvalGlobal");m.result().numerical(t).set("expr",new String[]{"ecs.I0_1","ecs.V0_2-ecs.V0_3"});double[][]v=m.result().numerical(t).getReal();x.put(k,k+","+(v[0][v[0].length-1]*1e3)+","+(v[1][v[1].length-1]*1e3)+","+(3*v[0][v[0].length-1]*1e3));PrintWriter w=new PrintWriter(new FileWriter(c));w.println("pressure_kPa,current_mA,voltage_mV,power_mW");for(String e:x.values())w.println(e);w.close();l.println("OK,"+x.get(k));l.flush();}m.study("std1").feature("param").active(z);m.save(q);}finally{l.close();ModelUtil.disconnect();}}}
